export function getDailyMindsetIndex(date = new Date()): number {
  const start = new Date(date.getFullYear(), 0, 1);
  const current = new Date(
    date.getFullYear(),
    date.getMonth(),
    date.getDate()
  );

  const diff = current.getTime() - start.getTime();
  const dayOfYear = Math.floor(diff / 86400000);

  // 365 fixed mindsets.
  // In leap years, Feb 29 reuses Feb 28's mindset.
  const index = Math.min(dayOfYear, 364);

  return index;
}

export function getDailyMindset(
  date = new Date()
): DailyMindset {
  const index = getDailyMindsetIndex(date);

  return dailyMindsets[index] ?? dailyMindsets[0];
}

export function getMindsetText(
  language: MindsetLanguage = "en",
  date = new Date()
): string {
  const mindset = getDailyMindset(language, date);

  return mindset[language] ?? mindset.en;
}
